 * - `text` parts become `{ text }` parts.
 * - `thought` parts become `{ text, thought: true }` parts, carrying the
 *   optional `thoughtSignature`.
 * - `media` parts with `data` become `inlineData` parts, defaulting `mimeType`
 *   to `application/octet-stream` when missing.
 * - `media` parts with `uri` become `fileData` parts.
 * - `media` parts with neither `data` nor `uri` are skipped.
 * - Any other variant is serialized to a `{ text }` part whose text is the
 *   JSON-stringified content part.
 */
export function contentPartsToGeminiParts(
  parts: ContentPart[] | undefined | null,
): Part[] {
  if (!parts) {
    return [];
  }

  const result: Part[] = [];

  for (const part of parts) {
    switch (part.type) {
      case 'text': {
        result.push({ text: part.text });
        break;
      }
      case 'thought': {
        const geminiPart: Part = { text: part.thought, thought: true };
        if (part.thoughtSignature !== undefined) {
          geminiPart.thoughtSignature = part.thoughtSignature;
        }
        result.push(geminiPart);
        break;
      }
      case 'media': {
        if (part.data !== undefined) {
          result.push({
            inlineData: {
              data: part.data,
              mimeType: part.mimeType ?? 'application/octet-stream',
            },
          });
        } else if (part.uri !== undefined) {
          result.push({
            fileData: {
              fileUri: part.uri,
              mimeType: part.mimeType,
            },
          });
        }
        // Media parts with neither data nor uri are skipped.
        break;
      }
      default: {
        result.push({ text: JSON.stringify(part) });
        break;
      }
    }
  }

  return result;
}

/**
 * Normalize a tool result's display value into {@link ContentPart}s.
 *
 * - `undefined` / `null` yield `undefined`.
 * - Strings yield a single text part.
 * - Anything else is JSON-stringified into a single text part.
 */
export function toolResultDisplayToContentParts(
  value: unknown,
): ContentPart[] | undefined {
  if (value === undefined || value === null) {
    return undefined;
  }
  if (typeof value === 'string') {
    return [{ type: 'text', text: value }];
  }
  return [{ type: 'text', text: JSON.stringify(value) }];
}

/** Recognized inputs used to build a tool response's structured data. */
export interface ToolResponseDataInput {
  /** Machine-readable error type (e.g. 'FILE_NOT_FOUND'). */
  errorType?: string;
  /** Path to a file the tool wrote output to. */
  outputFile?: string;
  /** Length of the content produced by the tool. */
  contentLength?: number;
  /** Additional structured data to merge into the result. */
